-- 4) Lotes, lineas, solicitudes y reparto. Se usa un bloque anonimo para
--    capturar los ID generados (RETURNING INTO) y enlazar sin suponer numeros.
DECLARE
  v_estado_pub   estado_donacion_ofrecida.id_estado_donacion_ofrecida%TYPE;
  v_estado_pend  estado_donacion.id_estado_donacion%TYPE;
  v_estado_asig  estado_donacion.id_estado_donacion%TYPE;
  v_lote1 NUMBER; v_lote2 NUMBER; v_lote3 NUMBER; v_lote4 NUMBER;
  v_ld1 NUMBER; v_ld2 NUMBER; v_ld3 NUMBER; v_ld4 NUMBER;
  v_ld5 NUMBER; v_ld6 NUMBER; v_ld7 NUMBER;
  v_don1 NUMBER; v_don2 NUMBER;
  v_org_olla NUMBER; v_org_comedor NUMBER; v_org_albergue NUMBER;

  FUNCTION f_alimento(p_nombre VARCHAR2) RETURN NUMBER IS
    v NUMBER;
  BEGIN
    SELECT id_alimento INTO v FROM alimento WHERE nombre_alimento = p_nombre;
    RETURN v;
  END;
  FUNCTION f_medida(p_nombre VARCHAR2) RETURN NUMBER IS
    v NUMBER;
  BEGIN
    SELECT id_unidad_medida INTO v FROM unidad_medida WHERE tipo_medida = p_nombre;
    RETURN v;
  END;
  FUNCTION f_org(p_nombre VARCHAR2) RETURN NUMBER IS
    v NUMBER;
  BEGIN
    SELECT id_organizacion INTO v FROM organizacion WHERE nombre_organizacion = p_nombre;
    RETURN v;
  END;
  PROCEDURE p_lote(p_donante VARCHAR2, p_id OUT NUMBER) IS
    v_dir  donante.direccion%TYPE;
    v_zona donante.id_zona%TYPE;
    v_don  donante.id_donante%TYPE;
  BEGIN
    -- INSERT ... SELECT no admite RETURNING en Oracle: se lee primero el donante
    SELECT id_donante, direccion, id_zona INTO v_don, v_dir, v_zona
      FROM donante WHERE nombre_donante = p_donante;
    INSERT INTO donacion_ofrecida (id_donante, id_estado_donacion_ofrecida, direccion, id_zona)
    VALUES (v_don, v_estado_pub, v_dir, v_zona)
    RETURNING id_donacion_ofrecida INTO p_id;
  END;
  PROCEDURE p_linea(p_lote NUMBER, p_alimento VARCHAR2, p_cant NUMBER, p_medida VARCHAR2,
                    p_peso NUMBER, p_costo NUMBER, p_venc DATE, p_cod VARCHAR2, p_id OUT NUMBER) IS
    v_ali NUMBER;
    v_med NUMBER;
  BEGIN
    -- Las funciones locales no pueden llamarse dentro de una sentencia SQL
    -- (PLS-00231): se evaluan antes y se pasan como variables.
    v_ali := f_alimento(p_alimento);
    v_med := f_medida(p_medida);
    INSERT INTO detalle_donacion_ofrecida (id_donacion_ofrecida, id_alimento, cantidad, id_unidad_medida,
                                           peso_total_kg, costo_unitario, fecha_vencimiento, codigo_lote)
    VALUES (p_lote, v_ali, p_cant, v_med, p_peso, p_costo, p_venc, p_cod)
    RETURNING id_detalle_donacion_ofrecida INTO p_id;
  END;
BEGIN
  SELECT id_estado_donacion_ofrecida INTO v_estado_pub  FROM estado_donacion_ofrecida WHERE estado = 'PUBLICADO';
  SELECT id_estado_donacion          INTO v_estado_pend FROM estado_donacion          WHERE estado = 'PENDIENTE';
  SELECT id_estado_donacion          INTO v_estado_asig FROM estado_donacion          WHERE estado = 'ASIGNADA';

  v_org_olla     := f_org('Olla Comun Santa Rosa');
  v_org_comedor  := f_org('Comedor Popular Las Flores');
  v_org_albergue := f_org('Albergue Casa Hogar');

  p_lote('Supermercado Metro Surco', v_lote1);
  p_lote('Panaderia La Union',       v_lote2);
  p_lote('Restaurante El Fogon',     v_lote3);
  p_lote('Supermercado Metro Surco', v_lote4);

  -- Lote 1 (Metro): pan de molde 40 u a 6.50 y leche 60 L a 4.20
  p_linea(v_lote1, 'Pan de molde integral',  40, 'Unidad',    16,  6.50, SYSDATE + 3, 'PM-0926', v_ld1);
  p_linea(v_lote1, 'Leche UHT entera 1L',    60, 'Litro',     60,  4.20, SYSDATE + 90,'LU-1126', v_ld2);
  -- Lote 2 (La Union): pan frances 15 kg a 8.00 y torta 3 u a 45.00
  p_linea(v_lote2, 'Pan frances',            15, 'Kilogramo', 15,  8.00, SYSDATE + 1, 'PF-0001', v_ld3);
  p_linea(v_lote2, 'Torta de chocolate',      3, 'Unidad',     4, 45.00, SYSDATE + 2, 'TC-0002', v_ld4);
  -- Lote 3 (El Fogon): platos preparados, vencen en horas (alimento perecible)
  p_linea(v_lote3, 'Arroz con pollo (porcion)',     25, 'Porcion', 10, 12.00, SYSDATE + 6/24,  'AP-0003', v_ld5);
  p_linea(v_lote3, 'Papa a la huancaina (porcion)', 25, 'Porcion',  8,  7.00, SYSDATE + 10/24, 'PH-0003', v_ld6);
  -- Lote 4 (Metro): yogur 30 L a 5.80
  p_linea(v_lote4, 'Yogur natural 1L',        30, 'Litro',     30,  5.80, SYSDATE + 7, 'YN-0004', v_ld7);

  -- Solicitudes (donacion_parcial) de las organizaciones sobre los lotes
  INSERT INTO donacion_parcial (id_donacion_ofrecida, id_organizacion, id_estado_donacion)
    VALUES (v_lote1, v_org_olla, v_estado_asig) RETURNING id_donacion_parcial INTO v_don1;
  INSERT INTO donacion_parcial (id_donacion_ofrecida, id_organizacion, id_estado_donacion)
    VALUES (v_lote2, v_org_comedor, v_estado_pend) RETURNING id_donacion_parcial INTO v_don2;
  INSERT INTO donacion_parcial (id_donacion_ofrecida, id_organizacion, id_estado_donacion)
    VALUES (v_lote3, v_org_olla, v_estado_pend);
  INSERT INTO donacion_parcial (id_donacion_ofrecida, id_organizacion, id_estado_donacion)
    VALUES (v_lote4, v_org_albergue, v_estado_pend);

  -- Reparto ya acordado: la olla recibe 40 u de pan y 30 L de leche del lote 1
  INSERT INTO detalle_donacion_parcial (id_donacion_parcial, id_detalle_donacion_ofrecida, cantidad) VALUES (v_don1, v_ld1, 40);
  INSERT INTO detalle_donacion_parcial (id_donacion_parcial, id_detalle_donacion_ofrecida, cantidad) VALUES (v_don1, v_ld2, 30);

  COMMIT;
END;
/

-- 5) Personas de recojo, despacho (con vehiculo) y responsable del primer reparto
INSERT INTO persona_recojo (id_organizacion, nombres, apellidos, id_tipo_documento, num_documento, sexo, telefono)
  SELECT o.id_organizacion, 'Rosa', 'Quispe Huaman', t.id_tipo_documento, '40111222', 'F', '987000111'
    FROM organizacion o, tipo_documento t
   WHERE o.nombre_organizacion = 'Olla Comun Santa Rosa' AND t.tipo_doc = 'DNI';

INSERT INTO despacho (id_donacion_parcial, id_vehiculo, fecha_programada)
  SELECT MIN(d.id_donacion_parcial),
         (SELECT id_vehiculo FROM vehiculo WHERE placa = 'TRI-001'),
         SYSTIMESTAMP + INTERVAL '2' HOUR
    FROM donacion_parcial d JOIN organizacion o ON o.id_organizacion = d.id_organizacion
   WHERE o.nombre_organizacion = 'Olla Comun Santa Rosa';

INSERT INTO despacho_responsable (id_despacho, id_persona_recojo)
  SELECT dr.id_despacho, p.id_persona_recojo
    FROM despacho dr, persona_recojo p
   WHERE p.num_documento = '40111222';

COMMIT;

-- 6) CRUD basico (UPDATE, DELETE y SELECT con condiciones y paginacion)
-- 6.1 UPDATE: la solicitud del comedor pasa a ASIGNADA
UPDATE donacion_parcial
   SET id_estado_donacion = (SELECT id_estado_donacion FROM estado_donacion WHERE estado = 'ASIGNADA')
 WHERE id_organizacion = (SELECT id_organizacion FROM organizacion
                           WHERE nombre_organizacion = 'Comedor Popular Las Flores');

-- 6.2 DELETE: se retira una solicitud PENDIENTE que aun no tiene reparto.
--     Los hijos (detalle, despacho, comprobante) bloquean el borrado por la
--     FK sin cascada, por eso se comprueba que no existan.
DELETE FROM donacion_parcial d
 WHERE d.id_estado_donacion = (SELECT id_estado_donacion FROM estado_donacion WHERE estado = 'PENDIENTE')
   AND d.id_organizacion    = (SELECT id_organizacion FROM organizacion
                                WHERE nombre_organizacion = 'Albergue Casa Hogar')
   AND NOT EXISTS (SELECT 1 FROM detalle_donacion_parcial x WHERE x.id_donacion_parcial = d.id_donacion_parcial)
   AND NOT EXISTS (SELECT 1 FROM despacho  r WHERE r.id_donacion_parcial = d.id_donacion_parcial)
   AND NOT EXISTS (SELECT 1 FROM comprobante c WHERE c.id_donacion_parcial = d.id_donacion_parcial);

-- 6.3 SELECT con IN, BETWEEN, LIKE, IS NOT NULL, ORDER BY y ROWNUM (11g)
SELECT * FROM (
SELECT a.nombre_alimento, l.fecha_vencimiento, l.cantidad, l.costo_unitario
  FROM detalle_donacion_ofrecida l
  JOIN alimento a ON a.id_alimento = l.id_alimento
 WHERE a.id_categoria_alimento IN (SELECT id_categoria_alimento FROM categoria_alimento
                                    WHERE nombre_categoria IN ('Panaderia', 'Lacteos'))
   AND l.costo_unitario BETWEEN 4 AND 10
   AND a.nombre_alimento LIKE 'Pan%'
   AND l.peso_total_kg IS NOT NULL
 ORDER BY l.fecha_vencimiento ASC, a.nombre_alimento
) WHERE ROWNUM <= 5;

COMMIT;
